//go:build linux
package main
import("bytes";"encoding/base64";"os";"path/filepath";"strings";"testing";"time")
func TestRebindCommitRollbackAndExternalEdit(t *testing.T){for _,mode:=range []string{"success","probe-failure","external-edit","stale"}{t.Run(mode,func(t *testing.T){a:=newApp(t.TempDir());a.sleep=func(time.Duration){};mkdir(a.p("/etc/config"));mkdir(a.p(vpnRoot));paths:=[]string{a.p("/etc/config/network"),a.p("/etc/config/podkop"),a.p("/etc/podkop-awg-failover.conf")};originals:=[][]byte{[]byte("network original"),[]byte("podkop original"),[]byte("MAIN_AWG='awg_backup'\nBACKUP_AWG='awg_main'\nBACKUP2_AWG='awg_backup2'\n")};for i,p:=range paths{os.WriteFile(p,originals[i],0600)};atomic(a.p(vpnRoot+"/podkop-section"),[]byte("main"));spec:=rebindFixture(t);expected:=obj(spec["expected"]);pubs:=map[string]string{};for i,s:=range slots{pub:=base64.StdEncoding.EncodeToString(bytes.Repeat([]byte{byte(i+1)},32));pubs[s]=pub;obj(expected[s])["fingerprint"]=hash([]byte(pub))};if mode=="stale"{obj(expected["awg_main"])["port"]=1000};mutations:=0
 a.run=func(_ time.Duration,input []byte,name string,args ...string)([]byte,error){sourceSlot:=func(s string)string{current,_:=read(paths[0]);if string(current)=="network changed"{return str(obj(spec["mapping"])[s])};return s};if name=="awg"&&len(args)==3{source:=sourceSlot(args[1]);switch args[2]{case "endpoints":return []byte("peer "+str(obj(expected[source])["host"])+":4340"),nil;case "public-key":return []byte(pubs[source]),nil}};if name=="ip"&&len(args)==6{source:=sourceSlot(args[5]);return []byte("1: "+args[5]+" inet "+str(obj(expected[source])["address"])+" scope global"),nil};if name=="uci"{if len(args)>0&&args[0]=="changes"{return nil,nil};if sameOrdered(args,[]string{"-q","get","podkop.main.interface"}){return []byte("awg_backup"),nil};if sameOrdered(args,[]string{"-q","-X","show","network"}){return []byte("network.awg_main=interface\nnetwork.awg_backup=interface\nnetwork.awg_backup2=interface\n"),nil};if len(args)==5&&args[0]=="-c"&&args[4]=="batch"{base:="network";if bytes.Contains(input,[]byte("commit podkop")){base="podkop"};return nil,os.WriteFile(filepath.Join(args[1],base),[]byte(base+" changed"),0600)}};if name=="ifdown"||name=="ifup"{mutations++;return nil,nil};if name==a.p("/etc/init.d/podkop")||name==a.p("/etc/init.d/podkop-awg-failover")||name==a.p("/usr/bin/home-net-install-verify"){mutations++;return nil,nil};if name=="curl"{if mode=="probe-failure"{return []byte("192.0.2.254"),nil};if mode=="external-edit"{os.WriteFile(paths[0],[]byte("operator edit"),0600);return []byte("192.0.2.254"),nil};for _,arg:=range args{if strings.HasPrefix(arg,"if!"){source:=sourceSlot(strings.TrimPrefix(arg,"if!"));return []byte(str(obj(expected[source])["host"])),nil}}};t.Fatalf("unexpected fixture command %s %q",name,args);return nil,errStopped}
 e:=a.applyRebind(spec);switch mode{case "success":if e!=nil{t.Fatal(e)};if exists(a.p(vpnRoot+"/rebind-pending")){t.Fatal("pending marker retained after verified apply")};for i,p:=range paths{current,_:=read(p);if bytes.Equal(current,originals[i]){t.Fatal("candidate not applied")}};case "probe-failure":if e==nil{t.Fatal("probe failure ignored")};for i,p:=range paths{current,_:=read(p);if !bytes.Equal(current,originals[i]){t.Fatal("rollback lost baseline")}};if exists(a.p(vpnRoot+"/rebind-pending")){t.Fatal("rollback not completed")};case "external-edit":if e==nil{t.Fatal("external edit ignored")};current,_:=read(paths[0]);if string(current)!="operator edit"||!exists(a.p(vpnRoot+"/rebind-pending")){t.Fatal("concurrent change overwritten or recovery record lost")};case "stale":if e==nil||mutations!=0{t.Fatal("stale snapshot caused mutations")};current,_:=read(paths[0]);if !bytes.Equal(current,originals[0]){t.Fatal("stale snapshot changed network")}}
 })}}
